class METSalesOrderLineCancelResponseContract extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_cancelResult">Result of the cancellation</param>
    /// <param name = "_cancelMessage">Message Result</param>
    /// <returns></returns>
    public static METSalesOrderLineCancelResponseContract newFromParameters(METProcessingStatus _cancelResult, Description255 _cancelMessage)
    {
        METSalesOrderLineCancelResponseContract salesOrderCancelLineResponse = new METSalesOrderLineCancelResponseContract();

        salesOrderCancelLineResponse.parmCancelResult(enum2Symbol(enumNum(METProcessingStatus), _cancelResult));
        salesOrderCancelLineResponse.parmCancelMessage(_cancelMessage);

        return salesOrderCancelLineResponse;
    }
